package main

import (
	"regexp"
	"fmt"
)

func isValidUsername(username string) bool {
	// Allow only alphanumeric characters and underscores, and must be 3-30 characters long
	re := regexp.MustCompile(`^[a-zA-Z0-9_]{3,30}$`)
	return re.MatchString(username)
}

func main() {
	// Test the username validation function
	fmt.Println(isValidUsername("valid_username")) // Expected: true
	fmt.Println(isValidUsername("invalid-username!")) // Expected: false
}

