package main

import (
	"mime/multipart"
	"net/http"
	"strings"
)

// Function to validate if the uploaded file is a PNG
func isPNG(fileHeader *multipart.FileHeader) bool {
	return strings.HasSuffix(fileHeader.Filename, ".png")
}

// Example usage
func main() {
	// Simulate a file upload
	fileHeader := &multipart.FileHeader{Filename: "profile.png"}
	if isPNG(fileHeader) {
		print("File is a valid PNG")
	} else {
		print("File is not a valid PNG")
	}
}
